// Unpack array of fields into individual items
const raw = $input.all();
const fields = raw[0]?.json?.fields || [];

return fields.map(field => ({
  json: {
    id: field.id,
    name: field.name,
    crop: field.crop,
    areaHa: field.areaHa,
    threshold: field.soilMoistureThreshold
  }
}));

const items = $input.all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const weather = items[i].json.weather || items[i].json;
  const field = $('Split Fields into Items').all()[i]?.json || {};

  const rainProb = Number(weather.rainProbability6h || 0);
  const rainMm = Number(weather.rainMm48h || 0);
  const tempMax = Number(weather.tempMax || 30);
  const riskBadges = weather.riskBadges || [];

  let hasRisk = false;
  let action = 'INSPECT';
  let severity = 'MEDIUM';
  let riskType = 'NORMAL';
  let messageEn = '';
  let messageBn = '';
  let reasoning = '';

  if (rainProb > 50 || rainMm >= 20 || riskBadges.includes('Heavy rain')) {
    hasRisk = true;
    riskType = 'HEAVY_RAIN';
    action = 'PAUSE_IRRIGATION';
    severity = 'HIGH';
    messageEn = `${field.name} (${field.crop}): Heavy rain forecast (${rainProb}% prob, ${rainMm}mm). Irrigation paused to avoid waterlogging.`;
    messageBn = `${field.name} (${field.crop}): আগামী ২৪ ঘণ্টায় ভারী বৃষ্টির সম্ভাবনা (${rainProb}%, ${rainMm} মিমি)। জলাবদ্ধতা এড়াতে সেচ বন্ধ রাখা হয়েছে।`;
    reasoning = `Daily 06:00 Climate Check: Rain probability is ${rainProb}% with ${rainMm}mm rainfall expected. Pausing irrigation and delaying spray.`;
  } else if (tempMax >= 38 || riskBadges.includes('Heat stress')) {
    hasRisk = true;
    riskType = 'HEATWAVE';
    action = 'IRRIGATE';
    severity = 'HIGH';
    messageEn = `${field.name} (${field.crop}): Extreme heatwave alert (${tempMax}°C max). Supplemental morning irrigation scheduled to mitigate heat stress.`;
    messageBn = `${field.name} (${field.crop}): তীব্র তাপপ্রবাহের সতর্কবার্তা (সর্বোচ্চ ${tempMax}°C)। ফসলের আর্দ্রতা বজায় রাখতে সম্পূরক সকালের সেচ নির্ধারণ করা হয়েছে।`;
    reasoning = `Daily 06:00 Climate Check: Forecast peak temperature is ${tempMax}°C. Supplemental cooling irrigation required.`;
  } else if (riskBadges.includes('Frost')) {
    hasRisk = true;
    riskType = 'FROST';
    action = 'INSPECT';
    severity = 'HIGH';
    messageEn = `${field.name} (${field.crop}): Frost warning detected. Inspect sensitive crop growth stages.`;
    messageBn = `${field.name} (${field.crop}): কুয়াশা ও শৈত্যপ্রবাহের ঝুঁকি শনাক্ত হয়েছে। সংবেদনশীল ফসল পরিদর্শন করুন।`;
    reasoning = `Daily 06:00 Climate Check: Low temperature/frost condition detected. Recommending manual field inspection.`;
  }

  results.push({
    json: {
      fieldId: field.id,
      fieldName: field.name,
      crop: field.crop,
      hasRisk,
      riskType,
      action,
      severity,
      messageEn,
      messageBn,
      reasoning,
      weather: {
        rainProbability6h: rainProb,
        rainMm48h: rainMm,
        tempMax
      }
    }
  });
}

return results;

